        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        line = br.readLine();
        if (line == null) return;
        int m = Integer.parseInt(line.trim());

        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

